    /// <summary>Number of distinct explicit allocations referenced by retail room states.</summary>
    public const int ExplicitDefinitionCount = 159;

    static RoomScrollDefinitions()
    {
        if (Definitions.Length != ExplicitDefinitionCount)
            throw new InvalidOperationException("Compiled room-scroll catalog cardinality is inconsistent.");

        for (int index = 0; index < Definitions.Length; index++)
        {
            if (Definitions[index].Storage.Length != RoomScrollGrid.StorageByteCount)
                throw new InvalidOperationException("Compiled room-scroll storage is not exactly 50 bytes.");
            if (index > 0 && Definitions[index - 1].Pointer >= Definitions[index].Pointer)
                throw new InvalidOperationException("Compiled room-scroll pointers must be unique and sorted.");
        }
    }

    /// <summary>Creates the native scroll allocation selected by one compiled room state.</summary>
    public static RoomScrollGrid CreateGrid(
        ISnesAddressSpace bus,
        ushort scrollPointer,
        int widthInScreens,
        int heightInScreens)
    {
        short signedPointer = unchecked((short)scrollPointer);
        return signedPointer < 0
            ? RoomScrollGrid.LoadCompiled(
                bus, Get(scrollPointer).Storage.Span, widthInScreens, heightInScreens)
            : RoomScrollGrid.CreateImplicit(
                bus, widthInScreens, heightInScreens,
                RoomScrollStates.FromCartridge(
                    unchecked((byte)(scrollPointer + 1)),
                    $"implicit scroll word ${scrollPointer:X4}"));
    }

    /// <summary>Returns one compiled explicit allocation by its bank-$8F pointer.</summary>
    public static RoomScrollDefinition Get(ushort pointer)
    {
        int low = 0;
        int high = Definitions.Length - 1;
        while (low <= high)
        {
            int middle = low + ((high - low) >> 1);
            int comparison = Definitions[middle].Pointer.CompareTo(pointer);
            if (comparison == 0) return Definitions[middle];
            if (comparison < 0) low = middle + 1;
            else high = middle - 1;
        }

        throw new ArgumentOutOfRangeException(nameof(pointer), pointer,
            "Pointer is not one of the 159 explicit retail room-scroll allocations.");
    }
}
